using RogControl;

public static class DeviceHotplugTests {
 static int checks;
 static readonly BindingFlags Hidden=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Check(bool value,string message){checks++;if(!value)throw new Exception(message);}
 static object Field(MainWindow window,string name){return typeof(MainWindow).GetField(name,Hidden).GetValue(window);}
 static object Invoke(MainWindow window,string name,params object[] args){return typeof(MainWindow).GetMethod(name,Hidden).Invoke(window,args);}
 static Dictionary<string,object> Map(params object[] pairs){var result=new Dictionary<string,object>();for(int i=0;i<pairs.Length;i+=2)result[(string)pairs[i]]=pairs[i+1];return result;}
 static Dictionary<string,object> Gear(string kind,int pid){return Map("kind",kind,"pid",pid,"deviceId","hid-0123456789abcdef","connected",true,"online",true,"readbackConfirmed",true,"snapshot",Map("modelPid",pid));}
 sealed class FakeNotifications : IDeviceHotplugNotifications {
  public readonly List<Guid> Kinds=new List<Guid>();public readonly List<IntPtr> Closed=new List<IntPtr>();public bool FailFirst,ThrowFirst,FailClose;
  public IntPtr Register(IntPtr window,Guid kind){Check(window==new IntPtr(71),"fake registration receives existing window only");Kinds.Add(kind);if(Kinds.Count==1&&ThrowFirst)throw new IOException("Synthetic registration error.");return Kinds.Count==1&&FailFirst?IntPtr.Zero:new IntPtr(Kinds.Count+100);}
  public bool Unregister(IntPtr notification){Closed.Add(notification);return !FailClose;}
 }
 static void Queue() {
  var queue=new DeviceHotplugQueue();long first;Check(!queue.Dirty&&!queue.Running&&!queue.Pending&&queue.Generation==0,"constructor has no automatic refresh");Check(!queue.TryBegin(10000,true,out first),"idle startup performs no discovery");queue.MarkChanged(0);Check(queue.Dirty&&queue.Pending&&queue.Generation==1,"change invalidates before any read");Check(!queue.TryBegin(749,true,out first),"750ms debounce is strict");Check(!queue.TryBegin(750,false,out first),"busy defers instead of discarding notification");Check(queue.TryBegin(750,true,out first)&&first==1,"idle settled change acquires one read");Check(queue.Dirty&&queue.Running&&!queue.Pending,"clearing pending cannot release bindings during refresh");long ignored;Check(!queue.TryBegin(900,true,out ignored),"refresh never overlaps itself");queue.Complete(first,true,1000);Check(!queue.Dirty&&!queue.Running,"successful current completion releases bindings");
  queue.MarkChanged(1100);Check(!queue.TryBegin(5749,true,out ignored),"refresh starts separated by at least five seconds");Check(queue.TryBegin(5750,true,out first),"five-second boundary accepted");queue.MarkChanged(6000);Check(!queue.IsCurrent(first)&&queue.Pending&&queue.Dirty,"new notification invalidates an in-flight read");queue.Complete(first,true,6100);Check(queue.Pending&&!queue.Running,"stale success retains a new read request");Check(!queue.TryBegin(6749,true,out ignored),"min interval remains in force after a stale completion");Check(queue.TryBegin(10750,true,out first),"later stable notification can be read");queue.Complete(first-1,true,10800);Check(queue.Running,"retired completion cannot release a newer read");queue.Complete(first,false,10800);Check(queue.Pending&&!queue.Running,"aborted/busy read is requeued");Check(!queue.TryBegin(15749,true,out ignored)&&queue.TryBegin(15750,true,out first),"failure retry respects minimum interval");queue.Stop();Check(queue.Stopped&&queue.Dirty&&!queue.IsCurrent(first),"stop invalidates an active lease until its task completes");queue.Complete(first,true,16000);Check(!queue.Dirty&&!queue.Running,"stopped completion cannot publish or retain polling");long old=queue.Generation;queue.MarkChanged(17000);queue.Stop();Check(queue.Generation==old&&!queue.TryBegin(Int64.MaxValue,true,out ignored),"stopped queue cannot restart");
  var burst=new DeviceHotplugQueue();for(int i=0;i<20;i++)burst.MarkChanged(i*100);Check(!burst.TryBegin(2649,true,out ignored)&&burst.TryBegin(2650,true,out first)&&first==20,"burst coalesces and last event resets debounce");burst.Complete(first,true,2651);
  var rewind=new DeviceHotplugQueue();rewind.MarkChanged(5000);Check(!rewind.TryBegin(4999,true,out ignored)&&rewind.TryBegin(5750,true,out first),"clock rewind cannot trigger an early read");
 }
 static void Coordinator() {
  long now=0;bool idle=true;int invalidations=0,reads=0;var queue=new DeviceHotplugQueue();var delayed=new TaskCompletionSource<bool>();
  var controller=new DeviceHotplugCoordinator(queue,()=>now,()=>idle,()=>invalidations++,ticket=>{reads++;Check(queue.IsCurrent(ticket),"refresher has current lease");return reads==1?delayed.Task:Task.FromResult(true);});
  controller.TickAsync().GetAwaiter().GetResult();Check(reads==0&&invalidations==0,"controller does not poll without a change");foreach(long code in new long[]{0,0x8001,0x8002,0x8005,0xFFFF,-1})Check(!controller.Notify(0x219,code),"query-removal/unknown messages are not consumed");Check(!controller.Notify(0,7)&&!queue.Dirty&&invalidations==0,"other window messages create no work");Check(controller.Notify(0x219,7)&&queue.Dirty&&invalidations==1&&reads==0,"hook only invalidates and marks dirty");now=750;idle=false;controller.TickAsync().GetAwaiter().GetResult();Check(queue.Pending&&reads==0,"idle guard is checked at execution time");idle=true;var pending=controller.TickAsync();Check(!pending.IsCompleted&&reads==1&&queue.Dirty,"deferred async refresh blocks binding readiness");controller.TickAsync().GetAwaiter().GetResult();Check(reads==1,"timer ticks do not duplicate an in-flight refresh");now=1000;controller.Notify(0x219,0x8004);delayed.SetResult(true);pending.GetAwaiter().GetResult();Check(queue.Pending&&!queue.Running&&invalidations==2,"disconnect during read rejects old completion");now=5750;controller.TickAsync().GetAwaiter().GetResult();Check(reads==2&&!queue.Dirty,"next current completion clears pending");
  foreach(long code in new long[]{0x8000,0x8003,0x8004})Check(DeviceHotplugCoordinator.RelevantMessage(0x219,code),"arrival/pending-removal/removal are recognized without lParam reads");queue.Stop();Check(!controller.Notify(0x219,7)&&invalidations==2,"closed observer cannot invalidate new state");
  var failureQueue=new DeviceHotplugQueue();int failures=0;now=0;var failure=new DeviceHotplugCoordinator(failureQueue,()=>now,()=>true,()=>{},ticket=>{failures++;if(failures==1)throw new IOException("Synthetic refresh failure.");return Task.FromResult(true);});failure.RequestRefresh();now=750;failure.TickAsync().GetAwaiter().GetResult();Check(failure.LastError=="IOException"&&failureQueue.Pending,"async error is observed and requeued");now=5749;failure.TickAsync().GetAwaiter().GetResult();Check(failures==1,"error does not create an immediate retry loop");now=5750;failure.TickAsync().GetAwaiter().GetResult();Check(failures==2&&!failureQueue.Dirty,"bounded retry can recover");
 }
 static void Registration() {
  Check(Marshal.SizeOf(typeof(DeviceHotplugInterfaceFilter))==32&&Marshal.OffsetOf(typeof(DeviceHotplugInterfaceFilter),"ClassGuid").ToInt32()==12&&Marshal.OffsetOf(typeof(DeviceHotplugInterfaceFilter),"NameFirst").ToInt32()==28,"DEV_BROADCAST_DEVICEINTERFACE_W ABI includes first UTF-16 name character");
  var native=new WindowsDeviceHotplugNotifications();Check(native!=null,"native adapter construction is inert");var fake=new FakeNotifications();var registry=new DeviceHotplugRegistration(fake);Check(fake.Kinds.Count==0&&!registry.Attach(IntPtr.Zero),"no registration before a valid existing HWND");Check(registry.Attach(new IntPtr(71))&&registry.Count==2,"both specific interfaces registered");Check(fake.Kinds.SequenceEqual(new[]{DeviceHotplugRegistration.HidInterface,DeviceHotplugRegistration.UsbInterface}),"documented HID and USB class identities");Check(!registry.Attach(new IntPtr(71))&&fake.Kinds.Count==2,"repeated SourceInitialized/Loaded cannot leak registrations");registry.Dispose();registry.Dispose();Check(fake.Closed.Count==2&&fake.Closed.Distinct().Count()==2&&registry.Count==0,"unregister each handle once");Check(!registry.Attach(new IntPtr(71))&&fake.Kinds.Count==2,"closed registry cannot recreate notifications");
  foreach(bool throwing in new[]{false,true}){fake=new FakeNotifications{FailFirst=!throwing,ThrowFirst=throwing,FailClose=true};using(var partial=new DeviceHotplugRegistration(fake)){Check(partial.Attach(new IntPtr(71))&&partial.Count==1,"one failed class does not hide the other notification class");}Check(fake.Closed.Count==1,"unregister remaining handle even when native return is false");}
 }
 static void Identity() {
  foreach(var pair in new[]{Tuple.Create("mouse",7546),Tuple.Create("mouse",7548),Tuple.Create("keyboard",7586),Tuple.Create("keyboard",7588),Tuple.Create("headset",7489)}){var gear=Gear(pair.Item1,pair.Item2);Check(DeviceHotplugReadFacts.GearIdentity(pair.Item1,gear)&&DeviceHotplugReadFacts.GearReadback(pair.Item1,"hid-0123456789abcdef",gear),"exact current adapter identity");gear["online"]=false;Check(DeviceHotplugReadFacts.GearReadback(pair.Item1,"hid-0123456789abcdef",gear),"confirmed offline state can replace a stale online snapshot");gear["readbackConfirmed"]=false;Check(!DeviceHotplugReadFacts.GearReadback(pair.Item1,"hid-0123456789abcdef",gear),"failed native read cannot become a connected snapshot");}
  foreach(int pid in new[]{0,7547,7549,7587,7589,6862})Check(!DeviceHotplugReadFacts.GearIdentity("mouse",Gear("mouse",pid)),"unknown device never becomes a supported mouse");var bad=Gear("mouse",7548);bad["deviceId"]="USB\\VID_0B05&PID_1D7C\\serial";Check(!DeviceHotplugReadFacts.GearIdentity("mouse",bad),"raw Windows path is not an adapter identity");bad=Gear("mouse",7548);bad["pid"]="7548";Check(!DeviceHotplugReadFacts.GearIdentity("mouse",bad),"PID type cannot be coerced");bad=Gear("mouse",7548);((Dictionary<string,object>)bad["snapshot"])["modelPid"]=7546;Check(!DeviceHotplugReadFacts.GearReadback("mouse","hid-0123456789abcdef",bad),"readback model must match route PID");Check(!DeviceHotplugReadFacts.GearReadback("mouse","hid-fedcba9876543210",Gear("mouse",7548)),"another peripheral cannot replace the selected route");Check(!DeviceHotplugReadFacts.GearIdentity("unknown",null),"absence stays unknown");
 }
 static void UnshownUi() {
  var window=new MainWindow(true);var notifications=new FakeNotifications();typeof(MainWindow).GetField("deviceHotplugNotifications",Hidden).SetValue(window,notifications);Invoke(window,"BeginDeviceHotplugMonitoring");Check(!(bool)Field(window,"deviceHotplugStarted")&&notifications.Kinds.Count==0,"render-only observer never registers native messages");Check(window.DeviceHotplugBindingsReady&&!window.DeviceHotplugPageReadsPaused&&window.DeviceHotplugCanPreviewReload,"render-only constructor has no pending refresh");
  typeof(MainWindow).GetField("render",Hidden).SetValue(window,false);Invoke(window,"BeginDeviceHotplugMonitoring");Invoke(window,"BeginDeviceHotplugMonitoring");Check((bool)Field(window,"deviceHotplugStarted")&&Field(window,"deviceHotplugTimer")==null&&notifications.Kinds.Count==0,"unshown observer only installs managed lifecycle callbacks");
  var sessions=(Dictionary<string,object>)Field(window,"gearReadSessions");sessions["mouse"]=new object();sessions["keyboard"]=new object();var snapshots=(Dictionary<string,Dictionary<string,object>>)Field(window,"gearStates");var original=Gear("mouse",7548);snapshots["mouse"]=original;long generation=window.DeviceHotplugGeneration;object[] args={IntPtr.Zero,0x219,new IntPtr(7),new IntPtr(1),false};Invoke(window,"DeviceHotplugMessage",args);Check(sessions.Count==0&&window.DeviceHotplugGeneration==generation+1,"notification invalidates tokens synchronously");Check(Object.ReferenceEquals(snapshots["mouse"],original),"hook never fabricates disconnected hardware readings");Check(window.DeviceHotplugPageReadsPaused&&!window.DeviceHotplugBindingsReady&&window.DeviceHotplugCanPreviewReload,"pending event pauses readers/bindings before any refresh");Check((bool)args[4]==false&&!(bool)Field(window,"busy")&&!(bool)Field(window,"mouseCalibrationWorkflowRunning"),"hook does not veto Windows or alter user workflows");Check(!((HardwareControlPolicy)Field(window,"hardwareControlPolicy")).Enabled,"observer does not grant hardware write permission");
  Invoke(window,"RequestDeviceHotplugRefresh");Check(window.DeviceHotplugGeneration==generation+2&&sessions.Count==0,"late-read signal schedules a new epoch without I/O");typeof(MainWindow).GetField("closing",Hidden).SetValue(window,true);sessions["mouse"]=new object();Invoke(window,"DeviceHotplugMessage",args);Check(window.DeviceHotplugGeneration==generation+3&&sessions.Count==0,"closing notification still invalidates calibration restore bindings");Invoke(window,"RequestDeviceHotplugRefresh");Check(window.DeviceHotplugGeneration==generation+3,"closing late-read signal cannot schedule new refresh I/O");((Task)Invoke(window,"WaitDeviceHotplugAsync")).GetAwaiter().GetResult();Invoke(window,"StopDeviceHotplugMonitoring");Check((bool)Field(window,"deviceHotplugStopped")&&Field(window,"deviceHotplugTimer")==null&&Field(window,"deviceHotplugSource")==null,"stop detaches managed/native lifecycle exactly once");long stopped=window.DeviceHotplugGeneration;Invoke(window,"DeviceHotplugMessage",args);Check(window.DeviceHotplugGeneration==stopped&&notifications.Kinds.Count==0,"stopped callback cannot recreate work");
  foreach(var field in typeof(MainWindow).GetFields(Hidden).Where(item=>item.FieldType==typeof(WorkerClient))){var worker=(WorkerClient)field.GetValue(window);Check(worker==null||typeof(WorkerClient).GetField("process",Hidden).GetValue(worker)==null,"notification callback creates no worker: "+field.Name);}Check(((Dictionary<string,WorkerClient>)Field(window,"sdkWorkers")).Count==0,"notification callback creates no SDK client");Check(new WindowInteropHelper(window).Handle==IntPtr.Zero&&!window.IsVisible&&PresentationSource.FromVisual(window)==null,"tests create no HWND or shown window");
 }
 [STAThread]public static int Main(){try{Queue();Coordinator();Registration();Identity();UnshownUi();Console.WriteLine(new JavaScriptSerializer().Serialize(new{ok=true,checks=checks,hardwareAccess=false,nativeNotifications=false,workerProcesses=0}));return 0;}catch(Exception error){Console.Error.WriteLine(error);return 1;}}
